INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('reconcile accounts', '', '', '[{"en":"The accountant reconciles accounts at the end of every month.","zh-TW":"會計師在每月末對帳。"},{"en":"Reconciling accounts helps detect errors and fraud.","zh-TW":"對帳有助於發現錯誤和欺詐。"}]', 'phrasal verb'),
('renewal rate', '', '', '[{"en":"The software''s renewal rate increased after new features were added.","zh-TW":"添加新功能後軟件的續約率提高了。"},{"en":"A high renewal rate indicates strong customer satisfaction.","zh-TW":"高續約率表明客戶滿意度高。"}]', 'phrasal verb'),
('report on findings', '', '', '[{"en":"The inspector will report on findings to the board next week.","zh-TW":"檢查員將於下週向董事會報告調查結果。"},{"en":"The team was asked to report on findings from the customer survey.","zh-TW":"團隊被要求報告客戶調查的調查結果。"}]', 'phrasal verb'),
('resource allocation plan', '', '', '[{"en":"The resource allocation plan was approved by the steering committee.","zh-TW":"資源分配計劃獲得了指導委員會的批准。"},{"en":"An accurate resource allocation plan prevents bottlenecks.","zh-TW":"準確的資源分配計劃可防止瓶頸。"}]', 'phrasal verb'),
('retention strategy', '', '', '[{"en":"A loyalty program is a key part of the customer retention strategy.","zh-TW":"忠誠度計劃是客戶留存策略的重要組成部分。"},{"en":"The retention strategy reduced employee turnover by 20%.","zh-TW":"留存策略將員工離職率降低了20%。"}]', 'phrasal verb'),
('risk exposure', '', '', '[{"en":"The bank reduced its risk exposure by diversifying its loan portfolio.","zh-TW":"銀行通過多元化貸款組合降低了風險敞口。"},{"en":"Currency risk exposure must be hedged in international contracts.","zh-TW":"國際合約中的貨幣風險敞口必須進行對沖。"}]', 'phrasal verb'),
('risk mitigation', '', '', '[{"en":"Risk mitigation plans were developed for all major project risks.","zh-TW":"為所有主要項目風險制定了風險緩解計劃。"},{"en":"Insurance is one form of risk mitigation for property damage.","zh-TW":"保險是財產損失的一種風險緩解形式。"}]', 'phrasal verb'),
('safety stock', '', '', '[{"en":"The company maintains a safety stock of 2 weeks of production materials.","zh-TW":"公司維持2週生產材料的安全庫存。"},{"en":"Safety stock acts as a buffer against unexpected supply disruptions.","zh-TW":"安全庫存作為應對意外供應中斷的緩衝。"}]', 'phrasal verb'),
('sales conversion rate', '', '', '[{"en":"Personalized follow-ups increased the sales conversion rate by 15%.","zh-TW":"個人化的跟進將銷售轉換率提高了15%。"},{"en":"A low sales conversion rate may indicate pricing or messaging issues.","zh-TW":"低銷售轉換率可能表明定價或訊息傳遞存在問題。"}]', 'phrasal verb'),
('service agreement', '', '', '[{"en":"The service agreement guarantees 24-hour response times.","zh-TW":"服務協議保證24小時響應時間。"},{"en":"Review the service agreement carefully before signing.","zh-TW":"在簽署前仔細審查服務協議。"}]', 'phrasal verb'),
('shareholder return', '', '', '[{"en":"The board''s primary goal is to maximize shareholder return.","zh-TW":"董事會的主要目標是最大化股東回報。"},{"en":"Dividends and capital gains both contribute to shareholder return.","zh-TW":"股息和資本收益都有助於股東回報。"}]', 'phrasal verb'),
('short-term liability', '', '', '[{"en":"Accounts payable is classified as a short-term liability.","zh-TW":"應付帳款被歸類為短期負債。"},{"en":"The company must manage short-term liabilities carefully.","zh-TW":"公司必須謹慎管理短期負債。"}]', 'phrasal verb'),
('site inspection', '', '', '[{"en":"A site inspection confirmed the construction met safety standards.","zh-TW":"現場檢查確認了建築符合安全標準。"},{"en":"The client requested a site inspection before signing the lease.","zh-TW":"客戶在簽署租約前要求進行現場檢查。"}]', 'phrasal verb'),
('staff productivity', '', '', '[{"en":"Flexible work arrangements increased staff productivity.","zh-TW":"彈性工作安排提高了員工生產力。"},{"en":"Staff productivity metrics include output per hour and error rates.","zh-TW":"員工生產力指標包括每小時產出和錯誤率。"}]', 'phrasal verb'),
('staff turnover rate', '', '', '[{"en":"A high staff turnover rate is costly due to recruitment and training.","zh-TW":"由於招募和培訓成本，高員工離職率代價高昂。"},{"en":"Improving work culture helped lower the staff turnover rate.","zh-TW":"改善工作文化有助於降低員工離職率。"}]', 'phrasal verb'),
('stock option plan', '', '', '[{"en":"The stock option plan attracted senior talent from competitors.","zh-TW":"股票選擇權計劃從競爭對手那裡吸引了高級人才。"},{"en":"Employees exercised their stock option plan shares after the IPO.","zh-TW":"首次公開招股後員工行使了股票選擇權計劃的股份。"}]', 'phrasal verb'),
('strategic planning process', '', '', '[{"en":"The strategic planning process involves SWOT analysis and goal-setting.","zh-TW":"戰略規劃流程涉及SWOT分析和目標設定。"},{"en":"Senior leaders participate in the annual strategic planning process.","zh-TW":"高層領導參與年度戰略規劃流程。"}]', 'phrasal verb'),
('supply chain visibility', '', '', '[{"en":"Real-time data improves supply chain visibility across all stages.","zh-TW":"實時數據改善了各階段的供應鏈可視性。"},{"en":"Greater supply chain visibility reduces the risk of stockouts.","zh-TW":"更強的供應鏈可視性降低了缺貨風險。"}]', 'phrasal verb'),
('sustainable procurement', '', '', '[{"en":"The company''s sustainable procurement policy favors eco-certified suppliers.","zh-TW":"公司的永續採購政策優先考慮環保認證供應商。"},{"en":"Sustainable procurement reduces carbon footprint across the supply chain.","zh-TW":"永續採購降低了整個供應鏈的碳足跡。"}]', 'phrasal verb'),
('tender submission', '', '', '[{"en":"The tender submission was completed and submitted before the deadline.","zh-TW":"投標提交在截止日期前完成並提交。"},{"en":"Tender submissions must include full pricing and technical details.","zh-TW":"投標提交必須包括完整的定價和技術細節。"}]', 'phrasal verb'),
('term deposit', '', '', '[{"en":"The company placed surplus funds in a six-month term deposit.","zh-TW":"公司將盈餘資金存入六個月期的定期存款。"},{"en":"Term deposit rates vary depending on the deposit amount and duration.","zh-TW":"定期存款利率根據存款金額和期限而有所不同。"}]', 'phrasal verb'),
('terms and conditions', '', '', '[{"en":"Customers must read the terms and conditions before creating an account.","zh-TW":"客戶在創建帳戶前必須閱讀條款與條件。"},{"en":"The terms and conditions specify the refund and cancellation policies.","zh-TW":"條款與條件規定了退款和取消政策。"}]', 'phrasal verb'),
('trade exposure', '', '', '[{"en":"The company''s trade exposure to China affects its earnings.","zh-TW":"公司對中國的貿易風險敞口影響其收益。"},{"en":"Hedging instruments are used to manage currency trade exposure.","zh-TW":"對沖工具用於管理貨幣貿易風險敞口。"}]', 'phrasal verb'),
('travel allowance', '', '', '[{"en":"Employees receive a daily travel allowance for business trips abroad.","zh-TW":"員工出差海外時每日收到差旅補貼。"},{"en":"The travel allowance covers transportation, accommodation, and meals.","zh-TW":"差旅補貼涵蓋交通、住宿和餐飲費用。"}]', 'phrasal verb'),
('trial period', '', '', '[{"en":"New employees undergo a 3-month trial period before confirmation.","zh-TW":"新員工在確認前接受3個月的試用期。"},{"en":"The software offers a 30-day trial period with full features.","zh-TW":"該軟件提供30天的全功能試用期。"}]', 'phrasal verb'),
('unfair dismissal', '', '', '[{"en":"The employee filed a lawsuit for unfair dismissal.","zh-TW":"員工提起了不公平解雇訴訟。"},{"en":"Unfair dismissal claims can result in compensation awards.","zh-TW":"不公平解雇索賠可能導致賠償裁決。"}]', 'phrasal verb'),
('vendor selection', '', '', '[{"en":"The vendor selection process included price, quality, and delivery evaluation.","zh-TW":"供應商選擇流程包括價格、品質和交貨評估。"},{"en":"A formal vendor selection process reduces procurement risk.","zh-TW":"正式的供應商選擇流程降低了採購風險。"}]', 'phrasal verb'),
('zone of negotiation', '', '', '[{"en":"Finding the zone of negotiation is the first step in any deal.","zh-TW":"找到談判空間是任何交易的第一步。"},{"en":"Both sides agreed there was a zone of negotiation between their offers.","zh-TW":"雙方同意在各自的出價之間存在議價區間。"}]', 'phrasal verb'),
('accounts receivable turnover', '', '', '[{"en":"A high accounts receivable turnover indicates efficient credit management.","zh-TW":"高應收帳款周轉率表明信用管理效率高。"},{"en":"The company improved its accounts receivable turnover by tightening credit terms.","zh-TW":"公司通過收緊信用條款改善了應收帳款周轉率。"}]', 'phrasal verb'),
('accrued liability', '', '', '[{"en":"Salaries payable are recorded as an accrued liability at month end.","zh-TW":"應付薪資在月末被記錄為應計負債。"},{"en":"Accrued liabilities appear in the current liabilities section of the balance sheet.","zh-TW":"應計負債出現在資產負債表的流動負債部分。"}]', 'phrasal verb'),
('active listening', '', '', '[{"en":"Active listening is critical in customer service and negotiations.","zh-TW":"積極傾聽在客戶服務和談判中至關重要。"},{"en":"Managers who use active listening build stronger team relationships.","zh-TW":"使用積極傾聽的管理者建立了更強的團隊關係。"}]', 'phrasal verb'),
('ad hoc', '', '', '[{"en":"An ad hoc committee was formed to handle the merger negotiations.","zh-TW":"一個臨時委員會成立以處理合併談判。"},{"en":"Ad hoc decisions should not replace a formal strategic process.","zh-TW":"臨時決策不應取代正式的戰略流程。"}]', 'phrasal verb'),
('administrative overhead', '', '', '[{"en":"Reducing administrative overhead was a key part of the cost-cutting plan.","zh-TW":"降低行政間接費用是削減成本計劃的重要組成部分。"},{"en":"Administrative overhead includes HR, finance, and legal department costs.","zh-TW":"行政間接費用包括人力資源、財務和法務部門的成本。"}]', 'phrasal verb'),
('advance payment guarantee', '', '', '[{"en":"The contractor provided an advance payment guarantee to the client.","zh-TW":"承包商向客戶提供了預付款保函。"},{"en":"An advance payment guarantee protects the buyer''s initial investment.","zh-TW":"預付款保函保護了買方的初始投資。"}]', 'phrasal verb'),
('agent of record', '', '', '[{"en":"The law firm was named agent of record for the insurance policy.","zh-TW":"律師事務所被指定為保險單的授權代理人。"},{"en":"An agent of record manages all communications with the insurer.","zh-TW":"授權代理人負責管理與保險公司的所有溝通。"}]', 'phrasal verb'),
('ancillary service', '', '', '[{"en":"The hotel generates revenue through ancillary services like parking.","zh-TW":"飯店通過停車等輔助服務產生收入。"},{"en":"Ancillary services are often bundled with the primary offering.","zh-TW":"輔助服務通常與主要產品捆綁在一起。"}]', 'phrasal verb'),
('arm''s length', '', '', '[{"en":"Tax authorities require related parties to transact on an arm''s length basis.","zh-TW":"稅務機關要求關聯方以公平交易為基礎進行交易。"},{"en":"The sale was conducted at arm''s length to avoid conflict of interest.","zh-TW":"銷售是在公平交易的基礎上進行的，以避免利益衝突。"}]', 'phrasal verb'),
('assess risk', '', '', '[{"en":"Managers must assess risk before approving capital expenditure.","zh-TW":"管理者在批准資本支出前必須評估風險。"},{"en":"The team assessed risk using a probability-impact matrix.","zh-TW":"團隊使用概率-影響矩陣評估了風險。"}]', 'phrasal verb'),
('asset management company', '', '', '[{"en":"The pension fund engaged an asset management company to grow returns.","zh-TW":"養老基金聘請了一家資產管理公司來增加回報。"},{"en":"Asset management companies charge fees based on assets under management.","zh-TW":"資產管理公司根據管理的資產規模收取費用。"}]', 'phrasal verb'),
('at-will employment', '', '', '[{"en":"At-will employment means the employer can terminate without advance notice.","zh-TW":"隨意雇用意味著雇主可以在不提前通知的情況下終止雇用。"},{"en":"Some states restrict at-will employment through protective legislation.","zh-TW":"一些州通過保護性立法限制了隨意雇用。"}]', 'phrasal verb'),
('authorization level', '', '', '[{"en":"Purchases above $10000 require manager authorization level approval.","zh-TW":"超過10,000元的採購需要經理授權級別的批准。"},{"en":"The authorization level for capital expenditure was raised to $50000.","zh-TW":"資本支出的授權級別提高到了5萬元。"}]', 'phrasal verb'),
('back office', '', '', '[{"en":"The bank upgraded its back office software to reduce processing errors.","zh-TW":"銀行升級了後台軟件以減少處理錯誤。"},{"en":"Back office functions include accounting, IT, and compliance.","zh-TW":"後台功能包括會計、IT和合規。"}]', 'phrasal verb'),
('benchmark analysis', '', '', '[{"en":"A benchmark analysis revealed the company lags peers in digital adoption.","zh-TW":"基準分析顯示公司在數位採用方面落後於同業。"},{"en":"Benchmark analysis is part of the annual strategic review process.","zh-TW":"基準分析是年度戰略審查流程的一部分。"}]', 'phrasal verb'),
('bilateral agreement', '', '', '[{"en":"The two countries signed a bilateral agreement to reduce tariffs.","zh-TW":"兩國簽署了一項雙邊協議以降低關稅。"},{"en":"A bilateral agreement on data sharing was reached after months of talks.","zh-TW":"經過數月談判，達成了一項數據共享的雙邊協議。"}]', 'phrasal verb'),
('blue-chip stock', '', '', '[{"en":"Blue-chip stocks provide stable dividends and lower volatility.","zh-TW":"藍籌股提供穩定的股息和較低的波動性。"},{"en":"Institutional investors favor blue-chip stocks for long-term portfolios.","zh-TW":"機構投資者青睞藍籌股用於長期投資組合。"}]', 'phrasal verb'),
('board resolution', '', '', '[{"en":"A board resolution was passed to approve the acquisition.","zh-TW":"通過了一項董事會決議以批准此次收購。"},{"en":"All major financial commitments require a board resolution.","zh-TW":"所有重大財務承諾都需要董事會決議。"}]', 'phrasal verb'),
('breach of warranty', '', '', '[{"en":"The customer filed a claim for breach of warranty on the defective product.","zh-TW":"客戶就有缺陷的產品提出了違反保固索賠。"},{"en":"Breach of warranty may entitle the buyer to a refund or replacement.","zh-TW":"違反保固可能使買方有權獲得退款或更換。"}]', 'phrasal verb'),
('break-even analysis', '', '', '[{"en":"Break-even analysis showed the product would be profitable after 6 months.","zh-TW":"損益平衡分析顯示該產品在6個月後將盈利。"},{"en":"Break-even analysis is essential before launching any new product.","zh-TW":"在推出任何新產品之前，損益平衡分析是必不可少的。"}]', 'phrasal verb'),
('capital expenditure budget', '', '', '[{"en":"The capital expenditure budget was cut by 30% due to the economic slowdown.","zh-TW":"由於經濟放緩，資本支出預算削減了30%。"},{"en":"A capital expenditure budget is reviewed and approved annually by the board.","zh-TW":"資本支出預算每年由董事會審查和批准。"}]', 'phrasal verb'),
('client acquisition', '', '', '[{"en":"Client acquisition costs decreased after optimizing the sales funnel.","zh-TW":"優化銷售漏斗後客戶獲取成本降低了。"},{"en":"A successful client acquisition strategy combines marketing and outreach.","zh-TW":"成功的客戶獲取策略結合了行銷和外聯活動。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('commission structure', '', '', '[{"en":"The new commission structure rewards top performers with higher rates.","zh-TW":"新的佣金結構以更高的費率獎勵頂尖表現者。"},{"en":"A transparent commission structure motivates the sales team.","zh-TW":"透明的佣金結構激勵了銷售團隊。"}]', 'phrasal verb'),
('consignment stock', '', '', '[{"en":"Consignment stock allows retailers to carry products with no upfront cost.","zh-TW":"寄售存貨使零售商可以在沒有前期成本的情況下持有產品。"},{"en":"The supplier reviews consignment stock levels monthly.","zh-TW":"供應商每月審查寄售存貨水平。"}]', 'phrasal verb'),
('cost benefit', '', '', '[{"en":"A cost benefit analysis showed the investment would yield positive returns.","zh-TW":"成本效益分析顯示投資將帶來正回報。"},{"en":"The team evaluated the cost benefit before upgrading the software.","zh-TW":"團隊在升級軟件前評估了成本效益。"}]', 'phrasal verb'),
('coverage ratio', '', '', '[{"en":"A coverage ratio above 2 is typically considered financially healthy.","zh-TW":"高於2的覆蓋比率通常被認為財務健康。"},{"en":"Lenders check the coverage ratio before extending credit facilities.","zh-TW":"貸款方在延伸信貸額度前檢查覆蓋比率。"}]', 'phrasal verb'),
('current ratio', '', '', '[{"en":"A current ratio above 1 means a company can pay its short-term debts.","zh-TW":"流動比率高於1意味著公司能夠償還其短期債務。"},{"en":"The company improved its current ratio by collecting overdue receivables.","zh-TW":"公司通過催收逾期應收帳款改善了其流動比率。"}]', 'phrasal verb'),
('differential pricing', '', '', '[{"en":"Airlines use differential pricing by charging more for peak-time flights.","zh-TW":"航空公司通過對高峰時段航班收取更多費用來實施差異化定價。"},{"en":"Differential pricing maximizes revenue across different customer segments.","zh-TW":"差異化定價在不同客戶群體中最大化了收入。"}]', 'phrasal verb'),
('direct mail', '', '', '[{"en":"The direct mail campaign generated a 5% response rate.","zh-TW":"直郵行銷活動產生了5%的響應率。"},{"en":"Direct mail is still effective for targeting older demographics.","zh-TW":"直郵行銷對於針對年齡較大的人口群體仍然有效。"}]', 'phrasal verb'),
('disclosure requirement', '', '', '[{"en":"Listed companies must comply with all disclosure requirements.","zh-TW":"上市公司必須遵守所有披露要求。"},{"en":"Failure to meet disclosure requirements can result in delisting.","zh-TW":"未能滿足披露要求可能導致摘牌。"}]', 'phrasal verb'),
('distributor network', '', '', '[{"en":"The company expanded its distributor network to 30 new countries.","zh-TW":"公司將其經銷商網絡擴展到了30個新國家。"},{"en":"A strong distributor network accelerates market penetration.","zh-TW":"強大的經銷商網絡加速了市場滲透。"}]', 'phrasal verb'),
('dividend payout', '', '', '[{"en":"The company increased its dividend payout to reward shareholders.","zh-TW":"公司增加了股息支付以回饋股東。"},{"en":"A high dividend payout ratio may indicate limited reinvestment in growth.","zh-TW":"高股息支付比率可能表明對增長的再投資有限。"}]', 'phrasal verb'),
('e-commerce platform', '', '', '[{"en":"The retailer launched an e-commerce platform to reach global customers.","zh-TW":"零售商推出了電子商務平台以觸及全球客戶。"},{"en":"An integrated e-commerce platform simplifies order and inventory management.","zh-TW":"整合的電子商務平台簡化了訂單和庫存管理。"}]', 'phrasal verb'),
('elasticity of demand', '', '', '[{"en":"Luxury goods have high elasticity of demand and sales drop with price rises.","zh-TW":"奢侈品的需求彈性高，價格上漲時銷售量下降。"},{"en":"Essential services have low elasticity of demand regardless of price.","zh-TW":"基本服務無論價格如何都具有低需求彈性。"}]', 'phrasal verb'),
('employee benefits package', '', '', '[{"en":"A comprehensive employee benefits package includes health and retirement plans.","zh-TW":"全面的員工福利套餐包括健康和退休計劃。"},{"en":"A competitive employee benefits package helps attract top candidates.","zh-TW":"有競爭力的員工福利套餐有助於吸引頂尖候選人。"}]', 'phrasal verb'),
('employee engagement survey', '', '', '[{"en":"The employee engagement survey showed 75% of staff feel valued.","zh-TW":"員工敬業度調查顯示75%的員工感到受重視。"},{"en":"Acting on employee engagement survey results improves retention.","zh-TW":"根據員工敬業度調查結果採取行動改善了留任率。"}]', 'phrasal verb'),
('escalation procedure', '', '', '[{"en":"The escalation procedure ensures critical issues reach senior management.","zh-TW":"升級程序確保重大問題能夠達到高層管理人員。"},{"en":"All customer complaints must follow the escalation procedure.","zh-TW":"所有客戶投訴必須遵循升級程序。"}]', 'phrasal verb'),
('exchange rate risk', '', '', '[{"en":"The importer hedged exchange rate risk using forward contracts.","zh-TW":"進口商使用遠期合約對沖了匯率風險。"},{"en":"Exchange rate risk is particularly relevant in cross-border transactions.","zh-TW":"匯率風險在跨境交易中尤為相關。"}]', 'phrasal verb'),
('exclusive distribution', '', '', '[{"en":"An exclusive distribution deal was signed for the Asia-Pacific region.","zh-TW":"簽署了亞太地區的獨家分銷協議。"},{"en":"Exclusive distribution limits competition but requires strong marketing efforts.","zh-TW":"獨家分銷限制了競爭，但需要強有力的行銷工作。"}]', 'phrasal verb'),
('expense reimbursement', '', '', '[{"en":"All expense reimbursement claims must be submitted with receipts.","zh-TW":"所有費用報銷申請必須附上收據提交。"},{"en":"The company updated its expense reimbursement policy for travel.","zh-TW":"公司更新了差旅費用報銷政策。"}]', 'phrasal verb'),
('fiduciary duty', '', '', '[{"en":"Directors owe a fiduciary duty to act in the best interest of shareholders.","zh-TW":"董事對股東負有以其最佳利益行事的受託義務。"},{"en":"Breaching fiduciary duty can lead to personal liability for executives.","zh-TW":"違反受託義務可能導致高管承擔個人責任。"}]', 'phrasal verb'),
('fixed asset register', '', '', '[{"en":"The fixed asset register must be updated when equipment is purchased.","zh-TW":"購買設備時必須更新固定資產登記冊。"},{"en":"An accurate fixed asset register supports depreciation calculations.","zh-TW":"準確的固定資產登記冊支持折舊計算。"}]', 'phrasal verb'),
('franchise agreement', '', '', '[{"en":"The franchise agreement outlines territory, royalties, and operational standards.","zh-TW":"特許經營協議概述了區域、特許使用費和運營標準。"},{"en":"Violating the franchise agreement may result in termination.","zh-TW":"違反特許經營協議可能導致終止。"}]', 'phrasal verb'),
('full-time equivalent', '', '', '[{"en":"The project requires 10 full-time equivalent staff to complete on time.","zh-TW":"該項目需要10名全職當量員工才能按時完成。"},{"en":"Budgeting is simplified by expressing staffing needs in full-time equivalents.","zh-TW":"通過以全職當量表示人員需求來簡化預算編製。"}]', 'phrasal verb'),
('gross profit margin', '', '', '[{"en":"The new pricing strategy increased the gross profit margin to 45%.","zh-TW":"新的定價策略將毛利率提高到了45%。"},{"en":"A declining gross profit margin may indicate rising production costs.","zh-TW":"下降的毛利率可能表明生產成本上升。"}]', 'phrasal verb'),
('high-net-worth individual', '', '', '[{"en":"Private banks offer personalized services to high-net-worth individuals.","zh-TW":"私人銀行為高淨值人士提供個性化服務。"},{"en":"High-net-worth individuals often require complex estate planning advice.","zh-TW":"高淨值人士通常需要複雜的遺產規劃建議。"}]', 'phrasal verb'),
('import tariff', '', '', '[{"en":"The government imposed an import tariff on steel to protect domestic producers.","zh-TW":"政府對鋼鐵徵收進口關稅以保護國內生產商。"},{"en":"Rising import tariffs increased the cost of raw materials.","zh-TW":"不斷上升的進口關稅增加了原材料成本。"}]', 'phrasal verb'),
('indemnification clause', '', '', '[{"en":"The indemnification clause protected the contractor from third-party claims.","zh-TW":"賠償條款保護了承包商免受第三方索賠。"},{"en":"Both parties agreed on a mutual indemnification clause in the agreement.","zh-TW":"雙方在協議中同意了相互賠償條款。"}]', 'phrasal verb'),
('indirect cost', '', '', '[{"en":"Rent and administrative salaries are classified as indirect costs.","zh-TW":"租金和行政薪資被歸類為間接成本。"},{"en":"Indirect costs must be allocated fairly across product lines.","zh-TW":"間接成本必須在各產品線中公平分配。"}]', 'phrasal verb'),
('interest rate swap', '', '', '[{"en":"The company used an interest rate swap to fix its borrowing cost.","zh-TW":"公司使用利率互換來固定其借貸成本。"},{"en":"Interest rate swaps help manage exposure to fluctuating interest rates.","zh-TW":"利率互換有助於管理對浮動利率的風險敞口。"}]', 'phrasal verb'),
('internal audit', '', '', '[{"en":"The internal audit revealed gaps in the expense approval process.","zh-TW":"內部審計揭示了費用批准流程中的漏洞。"},{"en":"Internal audits are conducted quarterly to ensure compliance.","zh-TW":"每季度進行內部審計以確保合規性。"}]', 'phrasal verb'),
('investment appraisal', '', '', '[{"en":"Net present value is a key method in investment appraisal.","zh-TW":"淨現值是投資評估的關鍵方法。"},{"en":"An investment appraisal was completed before the board approved funding.","zh-TW":"在董事會批准資金前完成了投資評估。"}]', 'phrasal verb'),
('job specification', '', '', '[{"en":"The job specification listed five years of experience as a minimum.","zh-TW":"職位規格將五年工作經驗列為最低要求。"},{"en":"Candidates who do not meet the job specification will not be shortlisted.","zh-TW":"不符合職位規格的候選人將不會進入短名單。"}]', 'phrasal verb'),
('joint liability', '', '', '[{"en":"All partners share joint liability for the firm''s debts.","zh-TW":"所有合夥人共同對公司的債務承擔連帶責任。"},{"en":"Joint liability ensures creditors can pursue any one of the parties.","zh-TW":"連帶責任確保債權人可以追究任何一方的責任。"}]', 'phrasal verb'),
('just-in-time delivery', '', '', '[{"en":"Just-in-time delivery reduces inventory holding costs significantly.","zh-TW":"準時制交貨顯著降低了庫存持有成本。"},{"en":"The factory runs on just-in-time delivery to avoid overproduction.","zh-TW":"工廠採用準時制交貨以避免生產過剩。"}]', 'phrasal verb'),
('labor dispute', '', '', '[{"en":"The labor dispute was settled through mediation after three weeks.","zh-TW":"勞資糾紛在三週後通過調解解決了。"},{"en":"A prolonged labor dispute can disrupt operations and damage brand reputation.","zh-TW":"長期的勞資糾紛可能會擾亂運營並損害品牌聲譽。"}]', 'phrasal verb'),
('late payment penalty', '', '', '[{"en":"The contract specifies a 2% late payment penalty on overdue invoices.","zh-TW":"合約規定對逾期發票收取2%的逾期付款罰款。"},{"en":"Clients received warnings before the late payment penalty was applied.","zh-TW":"在收取逾期付款罰款前向客戶發出了警告。"}]', 'phrasal verb'),
('launch campaign', '', '', '[{"en":"The launch campaign for the new product generated 10000 pre-orders.","zh-TW":"新產品的發布活動產生了1萬個預訂。"},{"en":"The launch campaign targeted social media to reach younger consumers.","zh-TW":"發布活動針對社交媒體觸及年輕消費者。"}]', 'phrasal verb'),
('long-term contract', '', '', '[{"en":"A long-term contract with the supplier locks in favorable pricing.","zh-TW":"與供應商的長期合約鎖定了有利的定價。"},{"en":"Long-term contracts provide revenue stability for service providers.","zh-TW":"長期合約為服務提供商提供了收入穩定性。"}]', 'phrasal verb'),
('mandatory disclosure', '', '', '[{"en":"All listed companies must make mandatory disclosure of material events.","zh-TW":"所有上市公司必須強制披露重大事件。"},{"en":"Failure to make mandatory disclosure can result in regulatory penalties.","zh-TW":"未能進行強制披露可能導致監管處罰。"}]', 'phrasal verb'),
('market segment', '', '', '[{"en":"The company focused on the premium market segment for its new product.","zh-TW":"公司將新產品聚焦在高端市場區隔。"},{"en":"Identifying the right market segment improves marketing ROI.","zh-TW":"識別正確的市場區隔改善了行銷投資回報率。"}]', 'phrasal verb'),
('market share growth', '', '', '[{"en":"Aggressive pricing contributed to significant market share growth.","zh-TW":"激進的定價促成了顯著的市場份額增長。"},{"en":"Market share growth is a key metric for assessing competitive success.","zh-TW":"市場份額增長是評估競爭成功的關鍵指標。"}]', 'phrasal verb'),
('merger and acquisition', '', '', '[{"en":"The merger and acquisition activity in the sector increased last year.","zh-TW":"去年該行業的併購活動有所增加。"},{"en":"A successful merger and acquisition requires thorough due diligence.","zh-TW":"成功的併購需要徹底的盡職調查。"}]', 'phrasal verb'),
('open account', '', '', '[{"en":"Open account terms allow buyers to pay within 30 days of delivery.","zh-TW":"賒帳條款允許買方在交貨後30天內付款。"},{"en":"Open account trading is common among established business partners.","zh-TW":"賒帳交易在老業務夥伴之間很常見。"}]', 'phrasal verb'),
('overdue invoice', '', '', '[{"en":"The accounts team sent reminders for all overdue invoices.","zh-TW":"帳務團隊為所有逾期發票發送了提醒。"},{"en":"An aging report helps prioritize collection of overdue invoices.","zh-TW":"應收帳款賬齡分析報告有助於優先催收逾期發票。"}]', 'phrasal verb'),
('payroll processing', '', '', '[{"en":"Automated payroll processing reduces errors and saves time.","zh-TW":"自動化薪資處理減少了錯誤並節省了時間。"},{"en":"The payroll processing team meets strict deadlines every month.","zh-TW":"薪資處理團隊每月都要遵守嚴格的截止日期。"}]', 'phrasal verb'),
('preferred shares', '', '', '[{"en":"Investors bought preferred shares for the guaranteed dividend yield.","zh-TW":"投資者購買優先股以獲得有保障的股息殖利率。"},{"en":"Preferred shares do not typically carry voting rights.","zh-TW":"優先股通常不附帶投票權。"}]', 'phrasal verb'),
('price-to-earnings ratio', '', '', '[{"en":"A high price-to-earnings ratio may indicate an overvalued stock.","zh-TW":"高本益比可能表明股票被高估了。"},{"en":"Investors compare the price-to-earnings ratio across industry peers.","zh-TW":"投資者比較同行業公司的本益比。"}]', 'phrasal verb'),
('proforma invoice', '', '', '[{"en":"The supplier sent a proforma invoice to confirm pricing and quantities.","zh-TW":"供應商發送了形式發票以確認定價和數量。"},{"en":"A proforma invoice is required to open a letter of credit.","zh-TW":"開立信用狀需要形式發票。"}]', 'phrasal verb'),
('project kickoff', '', '', '[{"en":"The project kickoff meeting introduced the timeline and responsibilities.","zh-TW":"項目啟動會議介紹了時間表和職責。"},{"en":"All stakeholders attended the project kickoff to align on expectations.","zh-TW":"所有利害關係人出席了項目啟動會議以對齊期望。"}]', 'phrasal verb'),
('public offering', '', '', '[{"en":"The company raised $200 million through a public offering on the stock exchange.","zh-TW":"公司通過股票交易所的公開發行籌集了2億元。"},{"en":"A public offering requires compliance with securities regulations.","zh-TW":"公開發行需要遵守證券法規。"}]', 'phrasal verb'),
('quality circle', '', '', '[{"en":"Quality circles helped reduce defects in the manufacturing line.","zh-TW":"品質圈幫助減少了製造線上的缺陷。"},{"en":"Employees in the quality circle proposed process improvements.","zh-TW":"品質圈中的員工提出了流程改進建議。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('quota system', '', '', '[{"en":"The government introduced a quota system to limit textile imports.","zh-TW":"政府引入了配額制度以限制紡織品進口。"},{"en":"A quota system helps protect domestic industries from foreign competition.","zh-TW":"配額制度有助於保護國內產業免受外國競爭。"}]', 'phrasal verb'),
('real-time data', '', '', '[{"en":"The operations team uses real-time data to monitor production lines.","zh-TW":"運營團隊使用實時數據監控生產線。"},{"en":"Real-time data enables faster and more accurate business decisions.","zh-TW":"實時數據使業務決策更快更準確。"}]', 'phrasal verb'),
('reimbursement claim', '', '', '[{"en":"Employees must submit a reimbursement claim within 30 days.","zh-TW":"員工必須在30天內提交報銷申請。"},{"en":"All reimbursement claims are reviewed by the finance department.","zh-TW":"所有報銷申請都由財務部門審查。"}]', 'phrasal verb'),
('release clause', '', '', '[{"en":"The release clause allowed the firm to exit the lease after two years.","zh-TW":"解除條款允許公司在兩年後退出租約。"},{"en":"The release clause was triggered by the project''s failure to proceed.","zh-TW":"解除條款因項目未能推進而被觸發。"}]', 'phrasal verb'),
('resource utilization', '', '', '[{"en":"High resource utilization means fewer idle assets and better returns.","zh-TW":"高資源利用率意味著更少的閒置資產和更好的回報。"},{"en":"Resource utilization reports help managers plan workloads efficiently.","zh-TW":"資源利用率報告幫助管理者有效地規劃工作量。"}]', 'phrasal verb'),
('return merchandise authorization', '', '', '[{"en":"Customers need a return merchandise authorization number to send items back.","zh-TW":"客戶需要退貨授權號碼才能退回商品。"},{"en":"The return merchandise authorization was processed within 24 hours.","zh-TW":"退貨授權在24小時內完成了處理。"}]', 'phrasal verb'),
('rolling forecast', '', '', '[{"en":"The finance team uses a rolling forecast instead of fixed annual budgets.","zh-TW":"財務團隊使用滾動預測而非固定年度預算。"},{"en":"A rolling forecast provides more accurate and current projections.","zh-TW":"滾動預測提供了更準確和最新的預測。"}]', 'phrasal verb'),
('scope of work', '', '', '[{"en":"The scope of work was agreed upon and signed before the project started.","zh-TW":"工作範圍在項目開始前已達成協議並簽署。"},{"en":"Changes outside the scope of work may incur additional charges.","zh-TW":"工作範圍以外的更改可能會產生額外費用。"}]', 'phrasal verb'),
('seasonal demand', '', '', '[{"en":"Retailers hire extra staff to manage seasonal demand during holidays.","zh-TW":"零售商在假期期間聘用額外員工來管理季節性需求。"},{"en":"Seasonal demand forecasting helps optimize inventory and staffing.","zh-TW":"季節性需求預測有助於優化庫存和人員配置。"}]', 'phrasal verb'),
('secured loan', '', '', '[{"en":"The company obtained a secured loan using its property as collateral.","zh-TW":"公司以其物業作抵押獲得了有擔保貸款。"},{"en":"Secured loans typically offer lower interest rates than unsecured ones.","zh-TW":"有擔保貸款通常比無擔保貸款提供更低的利率。"}]', 'phrasal verb'),
('service delivery', '', '', '[{"en":"The company redesigned its service delivery process to reduce wait times.","zh-TW":"公司重新設計了服務交付流程以減少等待時間。"},{"en":"Service delivery failures increase customer complaints and churn.","zh-TW":"服務交付失敗增加了客戶投訴和流失。"}]', 'phrasal verb'),
('service level', '', '', '[{"en":"The team consistently met all service level targets for the quarter.","zh-TW":"團隊在整個季度中持續達到了所有服務水平目標。"},{"en":"Customers who experience low service levels are more likely to churn.","zh-TW":"遭遇低服務水平的客戶更有可能流失。"}]', 'phrasal verb'),
('shareholder agreement', '', '', '[{"en":"The shareholder agreement outlines voting rights and dividend policies.","zh-TW":"股東協議概述了投票權和股息政策。"},{"en":"Disputes between shareholders are governed by the shareholder agreement.","zh-TW":"股東之間的糾紛由股東協議管轄。"}]', 'phrasal verb'),
('short selling', '', '', '[{"en":"Short selling can be profitable when a stock''s price falls.","zh-TW":"當股票價格下跌時，賣空可以帶來利潤。"},{"en":"Regulators banned short selling during the market crisis.","zh-TW":"監管機構在市場危機期間禁止了賣空。"}]', 'phrasal verb'),
('sinking fund', '', '', '[{"en":"The company set up a sinking fund to retire its bond debt.","zh-TW":"公司設立了償債基金以償還債券債務。"},{"en":"A sinking fund reduces the risk of default at maturity.","zh-TW":"償債基金降低了到期時違約的風險。"}]', 'phrasal verb'),
('social responsibility', '', '', '[{"en":"The company''s social responsibility program funds community schools.","zh-TW":"公司的社會責任計劃為社區學校提供資金。"},{"en":"Consumers increasingly choose brands with strong social responsibility.","zh-TW":"消費者越來越傾向於選擇具有強大社會責任感的品牌。"}]', 'phrasal verb'),
('sole proprietorship', '', '', '[{"en":"A sole proprietorship offers simplicity but involves personal liability.","zh-TW":"獨資企業結構簡單，但涉及個人責任。"},{"en":"Many small business owners start as a sole proprietorship.","zh-TW":"許多小企業主以獨資企業形式起步。"}]', 'phrasal verb'),
('span of control', '', '', '[{"en":"Reducing layers increased the span of control for each manager.","zh-TW":"減少管理層次增加了每位管理者的管理幅度。"},{"en":"A wide span of control requires strong communication and delegation skills.","zh-TW":"寬廣的管理幅度需要強大的溝通和授權技巧。"}]', 'phrasal verb'),
('stakeholder analysis', '', '', '[{"en":"A stakeholder analysis was completed at the project initiation stage.","zh-TW":"在項目啟動階段完成了利害關係人分析。"},{"en":"Stakeholder analysis helps prioritize engagement and communication efforts.","zh-TW":"利害關係人分析幫助優先考慮參與和溝通工作。"}]', 'phrasal verb'),
('stock split', '', '', '[{"en":"The company announced a 2-for-1 stock split to improve affordability.","zh-TW":"公司宣布進行2比1的股票分割以提高可負擔性。"},{"en":"A stock split increases the number of shares but does not change total market value.","zh-TW":"股票分割增加了股票數量，但不改變總市值。"}]', 'phrasal verb'),
('supply agreement', '', '', '[{"en":"A three-year supply agreement was signed to ensure pricing stability.","zh-TW":"簽署了三年供應協議以確保定價穩定。"},{"en":"The supply agreement includes volume commitments and delivery terms.","zh-TW":"供應協議包括數量承諾和交貨條款。"}]', 'phrasal verb'),
('syndicated loan', '', '', '[{"en":"The company raised $500 million through a syndicated loan from ten banks.","zh-TW":"公司通過來自十家銀行的聯合貸款籌集了5億元。"},{"en":"Syndicated loans spread credit risk among multiple lenders.","zh-TW":"聯合貸款在多個貸款方之間分散了信用風險。"}]', 'phrasal verb'),
('technology upgrade', '', '', '[{"en":"The technology upgrade improved system speed and data security.","zh-TW":"技術升級提高了系統速度和數據安全性。"},{"en":"A technology upgrade was approved to replace the legacy accounting software.","zh-TW":"批准了技術升級以取代舊版會計軟件。"}]', 'phrasal verb'),
('third-party auditor', '', '', '[{"en":"A third-party auditor confirmed the financial statements were accurate.","zh-TW":"第三方審計師確認了財務報表的準確性。"},{"en":"Hiring a third-party auditor builds credibility with investors.","zh-TW":"聘用第三方審計師建立了與投資者的信譽。"}]', 'phrasal verb'),
('trade payable', '', '', '[{"en":"The company extended its trade payable terms to 60 days.","zh-TW":"公司將應付貿易帳款條款延長到了60天。"},{"en":"Trade payables are listed as current liabilities on the balance sheet.","zh-TW":"應付貿易帳款在資產負債表上列為流動負債。"}]', 'phrasal verb'),
('training needs analysis', '', '', '[{"en":"The training needs analysis revealed a gap in project management skills.","zh-TW":"培訓需求分析揭示了項目管理技能方面的差距。"},{"en":"HR uses training needs analysis to plan the annual training calendar.","zh-TW":"人力資源部門使用培訓需求分析來規劃年度培訓日曆。"}]', 'phrasal verb'),
('unfunded pension liability', '', '', '[{"en":"The company disclosed a significant unfunded pension liability in its accounts.","zh-TW":"公司在賬目中披露了重大的未撥備養老金負債。"},{"en":"Unfunded pension liabilities increase the financial risk for employers.","zh-TW":"未撥備養老金負債增加了雇主的財務風險。"}]', 'phrasal verb'),
('value engineering', '', '', '[{"en":"Value engineering reduced the manufacturing cost by 18%.","zh-TW":"價值工程將製造成本降低了18%。"},{"en":"Value engineering focuses on delivering the same function at lower cost.","zh-TW":"價值工程專注於以較低的成本提供相同的功能。"}]', 'phrasal verb'),
('voting rights', '', '', '[{"en":"Common shareholders have voting rights while preferred shareholders often do not.","zh-TW":"普通股股東擁有投票權，而優先股股東通常沒有。"},{"en":"The merger required approval from shareholders with majority voting rights.","zh-TW":"合併需要獲得持有多數投票權的股東批准。"}]', 'phrasal verb'),
('accrual basis', '', '', '[{"en":"Most large companies prepare accounts on an accrual basis.","zh-TW":"大多數大型公司採用應計制編制帳目。"},{"en":"On an accrual basis, revenue is recognized when earned, not when received.","zh-TW":"在應計制下，收入在賺得時確認，而非在收到時。"}]', 'phrasal verb'),
('amortization schedule', '', '', '[{"en":"The amortization schedule shows the loan is paid off in 10 years.","zh-TW":"分期攤還計劃顯示貸款將在10年內還清。"},{"en":"Each payment in the amortization schedule reduces the outstanding principal.","zh-TW":"分期攤還計劃中的每次付款都減少了未償還本金。"}]', 'phrasal verb'),
('approved vendor list', '', '', '[{"en":"Only suppliers on the approved vendor list can receive purchase orders.","zh-TW":"只有在核准供應商名單上的供應商才能收到採購訂單。"},{"en":"The approved vendor list is reviewed annually for quality and compliance.","zh-TW":"核准供應商名單每年審查一次品質和合規情況。"}]', 'phrasal verb'),
('arm''s length price', '', '', '[{"en":"Tax authorities require related companies to transact at arm''s length prices.","zh-TW":"稅務機關要求關聯公司按公平交易價格進行交易。"},{"en":"An arm''s length price prevents profit shifting between group entities.","zh-TW":"公平交易價格防止了集團實體之間的利潤轉移。"}]', 'phrasal verb'),
('asset disposal', '', '', '[{"en":"The asset disposal generated $500000 for reinvestment.","zh-TW":"資產處置產生了50萬元用於再投資。"},{"en":"Proceeds from asset disposal were used to reduce company debt.","zh-TW":"資產處置所得用於減少公司債務。"}]', 'phrasal verb'),
('at par', '', '', '[{"en":"The bonds were issued at par and mature in five years.","zh-TW":"債券按面值發行，五年後到期。"},{"en":"Shares trading at par indicate market confidence in book value.","zh-TW":"按面值交易的股份表明市場對帳面價值有信心。"}]', 'phrasal verb'),
('back order', '', '', '[{"en":"Customers were notified that their orders were placed on back order.","zh-TW":"客戶被告知其訂單處於待補貨狀態。"},{"en":"The warehouse worked overtime to fulfill outstanding back orders.","zh-TW":"倉庫加班以完成未結的待補貨訂單。"}]', 'phrasal verb'),
('benchmarking exercise', '', '', '[{"en":"The benchmarking exercise identified areas where the company underperformed.","zh-TW":"標竿比較練習確定了公司表現不佳的領域。"},{"en":"A regular benchmarking exercise helps drive continuous improvement.","zh-TW":"定期的標竿比較練習有助於推動持續改進。"}]', 'phrasal verb'),
('bill of exchange', '', '', '[{"en":"The exporter drew a bill of exchange on the importer for payment.","zh-TW":"出口商向進口商開立了匯票以獲取付款。"},{"en":"A bill of exchange is commonly used in international trade finance.","zh-TW":"匯票在國際貿易融資中廣泛使用。"}]', 'phrasal verb'),
('capital adequacy', '', '', '[{"en":"The bank maintained capital adequacy above regulatory minimums.","zh-TW":"銀行維持了高於監管最低標準的資本充足率。"},{"en":"Capital adequacy rules were tightened after the 2008 financial crisis.","zh-TW":"2008年金融危機後資本充足率規則收緊了。"}]', 'phrasal verb'),
('cash and carry', '', '', '[{"en":"Small retailers buy stock from cash and carry wholesalers.","zh-TW":"小型零售商從現購自運批發商那裡購買庫存。"},{"en":"The cash and carry model reduces credit risk for the supplier.","zh-TW":"現購自運模式降低了供應商的信用風險。"}]', 'phrasal verb'),
('cash dividend', '', '', '[{"en":"The board declared a cash dividend of $0.50 per share.","zh-TW":"董事會宣布每股現金股息為0.50元。"},{"en":"Cash dividends are taxed as income in most jurisdictions.","zh-TW":"現金股息在大多數司法管轄區被視為收入徵稅。"}]', 'phrasal verb'),
('cash equivalents', '', '', '[{"en":"Money market funds are classified as cash equivalents on the balance sheet.","zh-TW":"貨幣市場基金在資產負債表上被歸類為現金等價物。"},{"en":"Cash equivalents improve a company''s liquidity position.","zh-TW":"現金等價物改善了公司的流動性狀況。"}]', 'phrasal verb'),
('claim settlement', '', '', '[{"en":"The insurance company completed claim settlement within 30 days.","zh-TW":"保險公司在30天內完成了理賠結案。"},{"en":"Claim settlement negotiations reduced the payout by 20%.","zh-TW":"索賠解決談判將賠付金額減少了20%。"}]', 'phrasal verb'),
('clearing house', '', '', '[{"en":"All stock trades are settled through the national clearing house.","zh-TW":"所有股票交易都通過國家清算所進行結算。"},{"en":"A clearing house reduces counterparty risk in financial markets.","zh-TW":"結算所降低了金融市場中的交易對手風險。"}]', 'phrasal verb'),
('compensation package', '', '', '[{"en":"The compensation package includes base salary, bonus, and stock options.","zh-TW":"薪酬套餐包括基本薪資、獎金和股票選擇權。"},{"en":"The CEO negotiated a competitive compensation package before joining.","zh-TW":"執行長在加入前談判了有競爭力的薪酬套餐。"}]', 'phrasal verb'),
('compliance audit', '', '', '[{"en":"The annual compliance audit found no significant violations.","zh-TW":"年度合規審計未發現重大違規行為。"},{"en":"A compliance audit provides assurance to regulators and management.","zh-TW":"合規審計為監管機構和管理層提供了保證。"}]', 'phrasal verb'),
('consumer confidence', '', '', '[{"en":"High consumer confidence typically leads to increased retail spending.","zh-TW":"高消費者信心通常會導致零售支出增加。"},{"en":"Consumer confidence fell after news of rising unemployment.","zh-TW":"失業率上升的消息傳出後，消費者信心下降了。"}]', 'phrasal verb'),
('contractual obligation', '', '', '[{"en":"The supplier met all its contractual obligations on time.","zh-TW":"供應商按時履行了所有合約義務。"},{"en":"Failure to meet contractual obligations may result in damages.","zh-TW":"未能履行合約義務可能導致賠償。"}]', 'phrasal verb'),
('cost driver', '', '', '[{"en":"Labor hours are the primary cost driver in this manufacturing process.","zh-TW":"勞動時間是此製造流程中的主要成本動因。"},{"en":"Understanding cost drivers enables more accurate budgeting.","zh-TW":"了解成本動因能夠實現更準確的預算編製。"}]', 'phrasal verb'),
('cost reduction initiative', '', '', '[{"en":"The cost reduction initiative saved 10% on annual operating expenses.","zh-TW":"降成本計劃節省了年度運營費用的10%。"},{"en":"All department heads were tasked with contributing to the cost reduction initiative.","zh-TW":"所有部門主管被要求為降成本計劃做出貢獻。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('counterfeit goods', '', '', '[{"en":"The customs authority seized a shipment of counterfeit goods.","zh-TW":"海關當局沒收了一批假冒商品。"},{"en":"Counterfeit goods damage brand reputation and reduce revenue.","zh-TW":"假冒商品損害了品牌聲譽並減少了收入。"}]', 'phrasal verb'),
('customer lifecycle', '', '', '[{"en":"Understanding the customer lifecycle improves retention and upselling.","zh-TW":"了解客戶生命週期改善了留存率和追加銷售。"},{"en":"Tailored communications at each customer lifecycle stage increase loyalty.","zh-TW":"在客戶生命週期的每個階段提供量身定制的溝通提高了忠誠度。"}]', 'phrasal verb'),
('cycle time', '', '', '[{"en":"Automation reduced the production cycle time from 8 hours to 3 hours.","zh-TW":"自動化將生產週期時間從8小時縮短到了3小時。"},{"en":"A shorter cycle time allows the company to fulfill orders faster.","zh-TW":"較短的週期時間使公司能夠更快地完成訂單。"}]', 'phrasal verb'),
('depreciation charge', '', '', '[{"en":"The annual depreciation charge for machinery is $50000.","zh-TW":"機械的年度折舊費用為5萬元。"},{"en":"Depreciation charges reduce taxable income but are non-cash expenses.","zh-TW":"折舊費用降低了應稅所得，但屬於非現金費用。"}]', 'phrasal verb'),
('directional strategy', '', '', '[{"en":"The board set a clear directional strategy focused on digital transformation.","zh-TW":"董事會制定了聚焦數位轉型的清晰方向性策略。"},{"en":"All business units aligned their plans with the corporate directional strategy.","zh-TW":"所有業務單位使其計劃與公司方向性策略保持一致。"}]', 'phrasal verb'),
('disposal value', '', '', '[{"en":"The disposal value of the equipment was estimated at 10% of cost.","zh-TW":"設備的處置價值估計為成本的10%。"},{"en":"Assets with a disposal value above zero are sold, not scrapped.","zh-TW":"處置價值高於零的資產被出售，而非報廢。"}]', 'phrasal verb'),
('dividend reinvestment plan', '', '', '[{"en":"The dividend reinvestment plan allows investors to compound returns automatically.","zh-TW":"股息再投資計劃允許投資者自動複利回報。"},{"en":"Many long-term investors use a dividend reinvestment plan to grow their holdings.","zh-TW":"許多長期投資者使用股息再投資計劃來增加其持股。"}]', 'phrasal verb'),
('end-of-day balance', '', '', '[{"en":"The bank sends an automated end-of-day balance notification.","zh-TW":"銀行發送自動化的日終餘額通知。"},{"en":"Treasury monitors the end-of-day balance to plan overnight financing.","zh-TW":"財務部門監控日終餘額以計劃隔夜融資。"}]', 'phrasal verb'),
('environmental impact assessment', '', '', '[{"en":"An environmental impact assessment was required before the factory was approved.","zh-TW":"在工廠獲批前需要進行環境影響評估。"},{"en":"The environmental impact assessment identified risks to local water resources.","zh-TW":"環境影響評估確定了對當地水資源的風險。"}]', 'phrasal verb'),
('expense account', '', '', '[{"en":"Business meals and travel can be charged to the expense account.","zh-TW":"商務餐和差旅費可以記入費用帳戶。"},{"en":"The expense account must be reconciled with receipts monthly.","zh-TW":"費用帳戶必須每月與收據進行對帳。"}]', 'phrasal verb'),
('face value', '', '', '[{"en":"The bond was issued at face value of $1000 per note.","zh-TW":"債券以每張1,000元的票面價值發行。"},{"en":"The face value of a share may differ significantly from its market value.","zh-TW":"股票的面值可能與其市場價值大不相同。"}]', 'phrasal verb'),
('financial reporting', '', '', '[{"en":"Quarterly financial reporting is required for all listed companies.","zh-TW":"所有上市公司都需要進行季度財務報告。"},{"en":"Transparent financial reporting builds investor trust.","zh-TW":"透明的財務報告建立了投資者信任。"}]', 'phrasal verb'),
('financial risk management', '', '', '[{"en":"The treasury team leads financial risk management for currency exposure.","zh-TW":"財務團隊負責主導貨幣風險敞口的財務風險管理。"},{"en":"A financial risk management policy includes liquidity and credit risk controls.","zh-TW":"財務風險管理政策包括流動性和信用風險控制。"}]', 'phrasal verb'),
('form of payment', '', '', '[{"en":"The invoice specifies wire transfer as the required form of payment.","zh-TW":"發票規定電匯為要求的付款方式。"},{"en":"Customers can choose their preferred form of payment at checkout.","zh-TW":"客戶可以在結帳時選擇其首選的付款方式。"}]', 'phrasal verb'),
('front-end loaded', '', '', '[{"en":"The project was front-end loaded with heavy design and planning costs.","zh-TW":"該項目在設計和規劃方面前期成本偏高。"},{"en":"Front-end loaded loans have higher interest in early repayment periods.","zh-TW":"前期費用偏高的貸款在早期還款期間利息較高。"}]', 'phrasal verb'),
('grant funding', '', '', '[{"en":"The startup secured grant funding for its renewable energy project.","zh-TW":"初創企業為其可再生能源項目獲得了補助資金。"},{"en":"Grant funding from the government supported the community development plan.","zh-TW":"政府的補助資金支持了社區發展計劃。"}]', 'phrasal verb'),
('gross margin analysis', '', '', '[{"en":"Gross margin analysis revealed that electronics had the highest profitability.","zh-TW":"毛利率分析顯示電子產品的盈利能力最高。"},{"en":"The CFO presented a gross margin analysis at the board review.","zh-TW":"財務長在董事會審查時提交了毛利率分析。"}]', 'phrasal verb'),
('guarantee fee', '', '', '[{"en":"The parent company charged a guarantee fee for backing the subsidiary loan.","zh-TW":"母公司因為子公司貸款提供擔保而收取了擔保費。"},{"en":"The guarantee fee was set at 0.5% of the facility amount annually.","zh-TW":"擔保費定為每年設施金額的0.5%。"}]', 'phrasal verb'),
('high-growth market', '', '', '[{"en":"Southeast Asia is seen as a high-growth market for e-commerce.","zh-TW":"東南亞被視為電子商務的高增長市場。"},{"en":"Investors seek high-growth markets to maximize portfolio returns.","zh-TW":"投資者尋求高增長市場以最大化投資組合回報。"}]', 'phrasal verb'),
('holding company', '', '', '[{"en":"The holding company owns a 70% stake in each subsidiary.","zh-TW":"控股公司擁有每家子公司70%的股份。"},{"en":"A holding company structure provides tax and liability advantages.","zh-TW":"控股公司結構提供了稅務和責任優勢。"}]', 'phrasal verb'),
('hurdle rate', '', '', '[{"en":"Projects must exceed the 12% hurdle rate to receive board approval.","zh-TW":"項目必須超過12%的門檻利率才能獲得董事會批准。"},{"en":"The hurdle rate accounts for the cost of capital and risk premium.","zh-TW":"門檻利率考慮了資本成本和風險溢酬。"}]', 'phrasal verb'),
('initial outlay', '', '', '[{"en":"The initial outlay for the new equipment was $1.5 million.","zh-TW":"新設備的初始支出為150萬元。"},{"en":"A low initial outlay makes the investment more accessible to smaller firms.","zh-TW":"低初始支出使較小的公司更容易進行投資。"}]', 'phrasal verb'),
('integrated report', '', '', '[{"en":"The company''s integrated report covers financial, ESG, and governance data.","zh-TW":"公司的整合報告涵蓋了財務、ESG和治理數據。"},{"en":"An integrated report provides a comprehensive view of value creation.","zh-TW":"整合報告提供了價值創造的全面視角。"}]', 'phrasal verb'),
('interest income', '', '', '[{"en":"The company earns interest income from its surplus cash deposits.","zh-TW":"公司從其盈餘現金存款中獲得利息收入。"},{"en":"Interest income is taxable and must be disclosed in financial reports.","zh-TW":"利息收入須繳稅，並必須在財務報告中披露。"}]', 'phrasal verb'),
('interim report', '', '', '[{"en":"The company''s interim report showed solid growth in the first half.","zh-TW":"公司的中期報告顯示上半年增長穩健。"},{"en":"Investors use interim reports to track performance between annual results.","zh-TW":"投資者使用中期報告來追蹤年度業績之間的表現。"}]', 'phrasal verb'),
('international trade finance', '', '', '[{"en":"Letters of credit are core tools in international trade finance.","zh-TW":"信用狀是國際貿易融資的核心工具。"},{"en":"International trade finance reduces payment risk for cross-border transactions.","zh-TW":"國際貿易融資降低了跨境交易的付款風險。"}]', 'phrasal verb'),
('inventory management system', '', '', '[{"en":"The inventory management system automatically triggers replenishment orders.","zh-TW":"庫存管理系統自動觸發補貨訂單。"},{"en":"An inventory management system reduces stockouts and overstock situations.","zh-TW":"庫存管理系統減少了缺貨和庫存過剩的情況。"}]', 'phrasal verb'),
('issued capital', '', '', '[{"en":"The company increased its issued capital through a rights issue.","zh-TW":"公司通過供股增加了已發行資本。"},{"en":"Issued capital appears in the equity section of the balance sheet.","zh-TW":"已發行資本出現在資產負債表的股東權益部分。"}]', 'phrasal verb'),
('job evaluation', '', '', '[{"en":"Job evaluation helps ensure fair and consistent pay structures.","zh-TW":"職位評估有助於確保公平一致的薪酬結構。"},{"en":"A job evaluation led to a redesign of the salary banding system.","zh-TW":"職位評估導致了薪資區間系統的重新設計。"}]', 'phrasal verb'),
('labour relations', '', '', '[{"en":"Good labour relations reduce the risk of industrial action.","zh-TW":"良好的勞動關係降低了工業行動的風險。"},{"en":"The HR department oversees labour relations and employee welfare.","zh-TW":"人力資源部門負責監督勞動關係和員工福利。"}]', 'phrasal verb'),
('long-term investment', '', '', '[{"en":"Property is often classified as a long-term investment on the balance sheet.","zh-TW":"房地產通常在資產負債表上被歸類為長期投資。"},{"en":"Long-term investments require patience but typically provide higher returns.","zh-TW":"長期投資需要耐心，但通常提供更高的回報。"}]', 'phrasal verb'),
('market entry barrier', '', '', '[{"en":"Regulatory requirements are a significant market entry barrier in healthcare.","zh-TW":"監管要求是醫療保健領域的重大市場進入壁壘。"},{"en":"High capital requirements create market entry barriers for new competitors.","zh-TW":"高資本要求為新競爭者創造了市場進入壁壘。"}]', 'phrasal verb'),
('market maker', '', '', '[{"en":"Market makers ensure continuous trading by quoting bid and ask prices.","zh-TW":"做市商通過報出買入價和賣出價確保持續交易。"},{"en":"The spread charged by a market maker is the primary source of revenue.","zh-TW":"做市商收取的差價是其主要收入來源。"}]', 'phrasal verb'),
('market research report', '', '', '[{"en":"The market research report showed strong demand for eco-friendly packaging.","zh-TW":"市場調研報告顯示對環保包裝的需求強勁。"},{"en":"Market research reports inform product development and marketing strategy.","zh-TW":"市場調研報告為產品開發和行銷策略提供了信息。"}]', 'phrasal verb'),
('mentoring program', '', '', '[{"en":"The mentoring program helped junior staff develop leadership skills.","zh-TW":"導師計劃幫助初級員工發展了領導技能。"},{"en":"Participants in the mentoring program reported higher job satisfaction.","zh-TW":"參與導師計劃的人員報告了更高的工作滿意度。"}]', 'phrasal verb'),
('milestone payment', '', '', '[{"en":"Milestone payments ensure the contractor is paid progressively.","zh-TW":"里程碑付款確保了承包商按進度獲得報酬。"},{"en":"The project contract includes four milestone payments tied to deliverables.","zh-TW":"項目合約包含與可交付成果掛鈎的四項里程碑付款。"}]', 'phrasal verb'),
('miscellaneous expenses', '', '', '[{"en":"Miscellaneous expenses were tracked separately in the expense report.","zh-TW":"雜項費用在費用報告中被單獨追蹤。"},{"en":"A budget line for miscellaneous expenses prevents overruns.","zh-TW":"雜項費用的預算項目可防止超支。"}]', 'phrasal verb'),
('net cash flow', '', '', '[{"en":"A positive net cash flow indicates the business generates more than it spends.","zh-TW":"正的淨現金流表明業務產生的現金多於支出。"},{"en":"The project''s net cash flow was negative in the first year due to setup costs.","zh-TW":"由於設置成本，項目第一年的淨現金流為負。"}]', 'phrasal verb'),
('net profit after tax', '', '', '[{"en":"Net profit after tax increased by 18% year over year.","zh-TW":"稅後淨利潤同比增長了18%。"},{"en":"Investors focus on net profit after tax as a true measure of profitability.","zh-TW":"投資者將稅後淨利潤作為盈利能力的真實衡量標準。"}]', 'phrasal verb'),
('new business development', '', '', '[{"en":"The company hired a VP to lead new business development in Asia.","zh-TW":"公司聘請了一位副總裁領導亞洲的新業務開發。"},{"en":"New business development requires strong networking and negotiation skills.","zh-TW":"新業務開發需要強大的網絡建立和談判技能。"}]', 'phrasal verb'),
('non-core asset', '', '', '[{"en":"The company sold its non-core assets to focus on core operations.","zh-TW":"公司出售了非核心資產以專注於核心業務。"},{"en":"Proceeds from non-core asset sales were used to reduce debt.","zh-TW":"非核心資產出售所得用於減少債務。"}]', 'phrasal verb'),
('non-recurring expense', '', '', '[{"en":"The restructuring charge was classified as a non-recurring expense.","zh-TW":"重組費用被歸類為一次性費用。"},{"en":"Analysts often exclude non-recurring expenses to assess underlying profitability.","zh-TW":"分析師通常排除非經常性費用以評估基礎盈利能力。"}]', 'phrasal verb'),
('normal operating conditions', '', '', '[{"en":"The warranty is valid under normal operating conditions only.","zh-TW":"保固僅在正常運營條件下有效。"},{"en":"Production resumed at full capacity after returning to normal operating conditions.","zh-TW":"在恢復正常運營條件後，生產恢復了全速運轉。"}]', 'phrasal verb'),
('notional value', '', '', '[{"en":"The notional value of the interest rate swap was $10 million.","zh-TW":"利率互換的名目價值為1000萬元。"},{"en":"Notional value differs from market value as it does not reflect actual cash flows.","zh-TW":"名目價值與市場價值不同，因為它不反映實際現金流量。"}]', 'phrasal verb'),
('objective setting', '', '', '[{"en":"Objective setting at the start of the year aligns teams with company goals.","zh-TW":"年初的目標設定使團隊與公司目標保持一致。"},{"en":"Clear objective setting improves performance and accountability.","zh-TW":"清晰的目標設定改善了績效和責任感。"}]', 'phrasal verb'),
('offshore account', '', '', '[{"en":"The company held an offshore account to manage foreign currency receipts.","zh-TW":"公司持有離岸帳戶以管理外幣收款。"},{"en":"Offshore accounts must comply with international tax reporting requirements.","zh-TW":"離岸帳戶必須遵守國際稅務申報要求。"}]', 'phrasal verb'),
('onboarding process', '', '', '[{"en":"A structured onboarding process helps new hires become productive faster.","zh-TW":"結構化的入職流程幫助新員工更快地提高生產力。"},{"en":"The client onboarding process involves identity verification and account setup.","zh-TW":"客戶入職流程包括身份驗證和帳戶設置。"}]', 'phrasal verb'),
('open purchase order', '', '', '[{"en":"The procurement team reviewed all open purchase orders each week.","zh-TW":"採購團隊每週審查所有未結採購訂單。"},{"en":"An open purchase order allows multiple deliveries against a single order.","zh-TW":"未結採購訂單允許針對單一訂單進行多次交貨。"}]', 'phrasal verb'),
('operating income', '', '', '[{"en":"Operating income grew by 12% following the cost reduction initiative.","zh-TW":"在降成本計劃後，營業收入增長了12%。"},{"en":"A high operating income indicates strong core business performance.","zh-TW":"高營業收入表明核心業務表現強勁。"}]', 'phrasal verb'),
('operating model', '', '', '[{"en":"The company redesigned its operating model to improve customer service.","zh-TW":"公司重新設計了其運營模式以改善客戶服務。"},{"en":"A lean operating model reduces costs without compromising quality.","zh-TW":"精益運營模式在不犧牲品質的情況下降低了成本。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('organizational effectiveness', '', '', '[{"en":"Leadership training improved organizational effectiveness across departments.","zh-TW":"領導力培訓改善了各部門的組織效能。"},{"en":"Organizational effectiveness is assessed through KPIs and employee surveys.","zh-TW":"組織效能通過關鍵績效指標和員工調查進行評估。"}]', 'phrasal verb'),
('outsourcing agreement', '', '', '[{"en":"The outsourcing agreement covers IT support and data management.","zh-TW":"外包協議涵蓋了IT支援和數據管理。"},{"en":"Service levels are defined in the outsourcing agreement.","zh-TW":"服務水平在外包協議中有所界定。"}]', 'phrasal verb'),
('passing off', '', '', '[{"en":"The company successfully sued a competitor for passing off its products.","zh-TW":"公司成功地起訴了一家以仿冒其產品的競爭對手。"},{"en":"Passing off can lead to significant legal damages and injunctions.","zh-TW":"商品混同可能導致重大法律損害賠償和禁令。"}]', 'phrasal verb'),
('patent protection', '', '', '[{"en":"Patent protection lasts 20 years from the date of filing.","zh-TW":"專利保護從申請日起持續20年。"},{"en":"Strong patent protection discourages competitors from copying innovations.","zh-TW":"強有力的專利保護阻止競爭者抄襲創新。"}]', 'phrasal verb'),
('price sensitivity', '', '', '[{"en":"In a commodity market, price sensitivity is very high.","zh-TW":"在商品市場中，價格敏感度非常高。"},{"en":"Understanding price sensitivity helps in setting optimal pricing strategies.","zh-TW":"了解價格敏感度有助於制定最佳定價策略。"}]', 'phrasal verb'),
('procurement process', '', '', '[{"en":"The company simplified its procurement process to reduce lead times.","zh-TW":"公司簡化了其採購流程以縮短交貨期。"},{"en":"A transparent procurement process ensures fair vendor selection.","zh-TW":"透明的採購流程確保了公平的供應商選擇。"}]', 'phrasal verb'),
('product liability', '', '', '[{"en":"The company purchased product liability insurance to protect against claims.","zh-TW":"公司購買了產品責任保險以防範索賠。"},{"en":"A product liability lawsuit forced a costly recall.","zh-TW":"產品責任訴訟迫使進行了代價高昂的召回。"}]', 'phrasal verb'),
('projected revenue', '', '', '[{"en":"The projected revenue for next year was set at $50 million.","zh-TW":"明年的預計收入定為5000萬元。"},{"en":"Actual results fell below projected revenue due to market slowdown.","zh-TW":"由於市場放緩，實際結果低於預計收入。"}]', 'phrasal verb'),
('quality standard', '', '', '[{"en":"All products must meet the ISO quality standard before shipment.","zh-TW":"所有產品在發貨前必須符合ISO品質標準。"},{"en":"Setting clear quality standards reduces defects and customer complaints.","zh-TW":"設定清晰的品質標準減少了缺陷和客戶投訴。"}]', 'phrasal verb'),
('reference check', '', '', '[{"en":"Reference checks confirmed the candidate had an excellent performance record.","zh-TW":"背景調查確認了候選人有出色的績效記錄。"},{"en":"All final candidates undergo a reference check before an offer is made.","zh-TW":"所有最終候選人在提出邀約前都要接受推薦人查核。"}]', 'phrasal verb'),
('registered office', '', '', '[{"en":"The registered office address must be available to the public.","zh-TW":"注冊辦公室地址必須向公眾公開。"},{"en":"Companies must notify the authorities if their registered office changes.","zh-TW":"如果公司的注冊辦公室地址有變更，必須通知有關機構。"}]', 'phrasal verb'),
('regulatory framework', '', '', '[{"en":"Financial institutions must operate within the regulatory framework.","zh-TW":"金融機構必須在監管框架內運營。"},{"en":"Changes to the regulatory framework affect compliance costs and practices.","zh-TW":"監管框架的變化影響了合規成本和做法。"}]', 'phrasal verb'),
('rejection letter', '', '', '[{"en":"All unsuccessful candidates received a rejection letter within a week.","zh-TW":"所有未成功的候選人在一週內收到了拒絕信。"},{"en":"A professional rejection letter maintains goodwill with future applicants.","zh-TW":"專業的拒絕信與未來的申請人保持了良好關係。"}]', 'phrasal verb'),
('remuneration package', '', '', '[{"en":"The executive''s remuneration package includes salary, bonus, and pension.","zh-TW":"高管的薪酬套餐包括薪資、獎金和退休金。"},{"en":"A competitive remuneration package helps attract senior talent.","zh-TW":"有競爭力的薪酬套餐有助於吸引高層人才。"}]', 'phrasal verb'),
('reputational risk', '', '', '[{"en":"A data breach creates significant reputational risk for the company.","zh-TW":"數據洩露對公司造成了重大聲譽風險。"},{"en":"Proactive crisis communication mitigates reputational risk.","zh-TW":"積極的危機溝通降低了聲譽風險。"}]', 'phrasal verb'),
('revenue growth', '', '', '[{"en":"The company achieved 15% revenue growth through new market entry.","zh-TW":"公司通過進入新市場實現了15%的收入增長。"},{"en":"Revenue growth is the primary metric for evaluating business performance.","zh-TW":"收入增長是評估業務績效的主要指標。"}]', 'phrasal verb'),
('rolling budget', '', '', '[{"en":"A rolling budget ensures projections remain current throughout the year.","zh-TW":"滾動預算確保預測在全年保持最新狀態。"},{"en":"The company switched to a rolling budget to improve financial agility.","zh-TW":"公司改用滾動預算以提高財務靈活性。"}]', 'phrasal verb'),
('sampling method', '', '', '[{"en":"A stratified sampling method was used to ensure representative survey results.","zh-TW":"使用了分層抽樣方法以確保代表性的調查結果。"},{"en":"The sampling method must be documented for audit purposes.","zh-TW":"抽樣方法必須為審計目的而記錄在案。"}]', 'phrasal verb'),
('secured creditor', '', '', '[{"en":"Secured creditors have priority over unsecured creditors in insolvency.","zh-TW":"有擔保債權人在破產時優先於無擔保債權人。"},{"en":"The bank acted as a secured creditor with a charge over company assets.","zh-TW":"銀行作為有擔保債權人，對公司資產持有抵押權。"}]', 'phrasal verb'),
('selling price', '', '', '[{"en":"The selling price was raised by 10% after raw material costs increased.","zh-TW":"在原材料成本上漲後，售價提高了10%。"},{"en":"The selling price must cover costs and provide an acceptable profit margin.","zh-TW":"售價必須涵蓋成本並提供可接受的利潤率。"}]', 'phrasal verb'),
('short-term financing', '', '', '[{"en":"The company used short-term financing to cover its seasonal cash needs.","zh-TW":"公司使用短期融資來滿足其季節性現金需求。"},{"en":"Short-term financing is more flexible but typically carries higher interest.","zh-TW":"短期融資更靈活，但通常利率較高。"}]', 'phrasal verb'),
('skill assessment', '', '', '[{"en":"A skill assessment was completed for all staff before training began.","zh-TW":"所有員工在培訓開始前完成了技能評估。"},{"en":"Skill assessments help match employees to the right development programs.","zh-TW":"技能評估有助於將員工與合適的發展計劃相匹配。"}]', 'phrasal verb'),
('stakeholder value', '', '', '[{"en":"A stakeholder value approach considers employees, customers, and communities.","zh-TW":"利害關係人價值方法考慮了員工、客戶和社區。"},{"en":"Companies increasingly report on stakeholder value beyond shareholder returns.","zh-TW":"越來越多的公司報告了股東回報之外的利害關係人價值。"}]', 'phrasal verb'),
('standard deviation', '', '', '[{"en":"A low standard deviation indicates consistent performance.","zh-TW":"低標準差表明績效一致。"},{"en":"Risk analysts use standard deviation to measure investment volatility.","zh-TW":"風險分析師使用標準差來衡量投資波動性。"}]', 'phrasal verb'),
('starting capital', '', '', '[{"en":"The entrepreneur raised starting capital from family and angel investors.","zh-TW":"企業家從家人和天使投資人那裡籌集了啟動資金。"},{"en":"Starting capital is used to cover initial costs like equipment and marketing.","zh-TW":"啟動資金用於涵蓋設備和行銷等初始成本。"}]', 'phrasal verb'),
('stock replenishment', '', '', '[{"en":"The inventory system sends automatic alerts for stock replenishment.","zh-TW":"庫存系統發送自動補貨提醒。"},{"en":"Timely stock replenishment prevents stockouts during peak demand.","zh-TW":"及時的補貨在需求高峰期間防止了缺貨。"}]', 'phrasal verb'),
('strategic review', '', '', '[{"en":"The board commissioned a strategic review of the company''s global operations.","zh-TW":"董事會委託進行了公司全球運營的戰略審查。"},{"en":"A strategic review may result in significant changes to the business model.","zh-TW":"戰略審查可能導致商業模式的重大變化。"}]', 'phrasal verb'),
('surplus inventory', '', '', '[{"en":"The company launched a clearance sale to reduce surplus inventory.","zh-TW":"公司啟動了清倉銷售以減少庫存積壓。"},{"en":"Surplus inventory ties up working capital and increases storage costs.","zh-TW":"過剩庫存佔用了營運資金並增加了存儲成本。"}]', 'phrasal verb'),
('swap agreement', '', '', '[{"en":"The company entered a swap agreement to convert variable to fixed interest.","zh-TW":"公司簽訂了互換協議將浮動利率轉換為固定利率。"},{"en":"Swap agreements are commonly used to manage currency and interest rate risk.","zh-TW":"互換協議常用於管理貨幣和利率風險。"}]', 'phrasal verb'),
('tax exemption', '', '', '[{"en":"The nonprofit organization applied for a tax exemption on its income.","zh-TW":"非牟利組織申請了其收入的稅收豁免。"},{"en":"Special economic zones offer tax exemptions to attract foreign investment.","zh-TW":"特殊經濟區提供稅收豁免以吸引外資。"}]', 'phrasal verb'),
('tax incentive', '', '', '[{"en":"The government offered a tax incentive to firms investing in green energy.","zh-TW":"政府為投資綠色能源的公司提供了稅收優惠。"},{"en":"Tax incentives for R&D spending have increased innovation activity.","zh-TW":"研發支出的稅收優惠增加了創新活動。"}]', 'phrasal verb'),
('technology transfer', '', '', '[{"en":"The technology transfer agreement allowed the licensee to manufacture locally.","zh-TW":"技術轉讓協議允許被授權方在當地製造。"},{"en":"Technology transfer between universities and industry drives innovation.","zh-TW":"大學和產業之間的技術轉讓推動了創新。"}]', 'phrasal verb'),
('third-party vendor', '', '', '[{"en":"The IT department evaluated five third-party vendors for the new software.","zh-TW":"IT部門評估了五家第三方供應商以選擇新軟件。"},{"en":"Third-party vendors must adhere to the company''s quality and security standards.","zh-TW":"第三方供應商必須遵守公司的品質和安全標準。"}]', 'phrasal verb'),
('total revenue', '', '', '[{"en":"Total revenue for the year reached $80 million.","zh-TW":"全年總收入達到了8000萬元。"},{"en":"Total revenue growth of 12% exceeded analyst expectations.","zh-TW":"12%的總收入增長超過了分析師預期。"}]', 'phrasal verb'),
('trade association', '', '', '[{"en":"The company joined the trade association to influence industry regulations.","zh-TW":"公司加入了行業協會以影響行業法規。"},{"en":"Trade associations provide networking, advocacy, and industry research.","zh-TW":"行業協會提供網絡建立、倡導和行業研究服務。"}]', 'phrasal verb'),
('trade embargo', '', '', '[{"en":"The trade embargo restricted all exports to the targeted country.","zh-TW":"貿易禁運限制了對目標國家的所有出口。"},{"en":"A trade embargo can disrupt global supply chains and raise prices.","zh-TW":"貿易禁運可能會擾亂全球供應鏈並推高價格。"}]', 'phrasal verb'),
('trade finance', '', '', '[{"en":"Letters of credit and guarantees are key tools in trade finance.","zh-TW":"信用狀和擔保是貿易融資的關鍵工具。"},{"en":"Trade finance reduces payment risk for buyers and sellers in different countries.","zh-TW":"貿易融資降低了不同國家買賣雙方的付款風險。"}]', 'phrasal verb'),
('treasury function', '', '', '[{"en":"The treasury function oversees currency hedging and short-term borrowing.","zh-TW":"財務管理職能負責監督貨幣對沖和短期借款。"},{"en":"Centralizing the treasury function improves visibility and control of cash.","zh-TW":"集中財務管理職能改善了現金的可視性和控制。"}]', 'phrasal verb'),
('unsecured bond', '', '', '[{"en":"The company issued unsecured bonds at a higher interest rate.","zh-TW":"公司以較高的利率發行了無擔保債券。"},{"en":"Unsecured bondholders rank below secured creditors in insolvency.","zh-TW":"在破產時，無擔保債券持有人排在有擔保債權人之後。"}]', 'phrasal verb'),
('valuation method', '', '', '[{"en":"The most common valuation method for businesses is discounted cash flow.","zh-TW":"最常見的企業估值方法是折現現金流法。"},{"en":"The valuation method affects the final price agreed in a merger.","zh-TW":"估值方法影響了合併中商定的最終價格。"}]', 'phrasal verb'),
('value-added tax', '', '', '[{"en":"Businesses must register for value-added tax above a certain revenue threshold.","zh-TW":"收入超過一定門檻的企業必須登記徵收增值稅。"},{"en":"Value-added tax is a major source of government revenue.","zh-TW":"增值稅是政府收入的主要來源。"}]', 'phrasal verb'),
('year-end audit', '', '', '[{"en":"The external auditors completed the year-end audit within four weeks.","zh-TW":"外部審計師在四週內完成了年終審計。"},{"en":"A clean year-end audit result builds confidence with investors.","zh-TW":"清潔的年終審計結果建立了投資者的信心。"}]', 'phrasal verb'),
('allocation of resources', '', '', '[{"en":"Efficient allocation of resources maximizes organizational output.","zh-TW":"有效的資源分配最大化了組織產出。"},{"en":"The annual plan includes an allocation of resources to each department.","zh-TW":"年度計劃包括向每個部門的資源分配。"}]', 'phrasal verb'),
('allowance for doubtful accounts', '', '', '[{"en":"The accountant increased the allowance for doubtful accounts after reviewing aging.","zh-TW":"會計師在審查帳齡後增加了呆帳準備金。"},{"en":"An allowance for doubtful accounts reduces net receivables on the balance sheet.","zh-TW":"呆帳準備金降低了資產負債表上的淨應收帳款。"}]', 'phrasal verb'),
('ask price', '', '', '[{"en":"The ask price for the shares was $10.50 per unit.","zh-TW":"股份的賣出價為每單位10.50元。"},{"en":"The difference between bid and ask price is called the spread.","zh-TW":"買入價和賣出價之間的差額稱為差價。"}]', 'phrasal verb'),
('asset impairment', '', '', '[{"en":"An asset impairment charge was recognized after the plant closure.","zh-TW":"工廠關閉後確認了資產減值費用。"},{"en":"Annual asset impairment tests are required by international accounting standards.","zh-TW":"國際會計準則要求進行年度資產減值測試。"}]', 'phrasal verb'),
('asset turnover', '', '', '[{"en":"A high asset turnover ratio indicates efficient use of company assets.","zh-TW":"高資產周轉率表明公司資產使用效率高。"},{"en":"The company improved asset turnover by disposing of underperforming assets.","zh-TW":"公司通過處置業績不佳的資產改善了資產周轉率。"}]', 'phrasal verb'),
('average collection period', '', '', '[{"en":"The average collection period decreased from 45 to 30 days.","zh-TW":"平均收款期從45天縮短到了30天。"},{"en":"A shorter average collection period improves cash flow management.","zh-TW":"較短的平均收款期改善了現金流管理。"}]', 'phrasal verb'),
('back-office operations', '', '', '[{"en":"Automating back-office operations reduced processing time by 40%.","zh-TW":"自動化後台運營將處理時間縮短了40%。"},{"en":"Back-office operations include transaction processing and compliance reporting.","zh-TW":"後台運營包括交易處理和合規報告。"}]', 'phrasal verb'),
('balance brought forward', '', '', '[{"en":"The balance brought forward was $15000 from the previous month.","zh-TW":"上月結轉的期初餘額為15,000元。"},{"en":"Balance brought forward ensures continuity between accounting periods.","zh-TW":"結轉餘額確保了會計期間之間的連續性。"}]', 'phrasal verb');